\set ON_ERROR_STOP on
\copy (SELECT a.*,e.company_name FROM employer_monitoring_audits a JOIN employers e USING(employer_id) WHERE a.monitoring_tier='A' ORDER BY e.company_name) TO 'exports/tier_a_source_audits_2026-08-31.csv' CSV HEADER
\copy (SELECT ms.*,e.company_name FROM monitored_sources ms JOIN employers e USING(employer_id) WHERE ms.priority_tier='A' ORDER BY e.company_name,ms.source_priority,ms.source_name) TO 'exports/monitored_sources_a_tier_2026-08-31.csv' CSV HEADER
\copy (SELECT o.*,e.company_name FROM opportunities o JOIN employers e USING(employer_id) JOIN employer_audits a USING(employer_id) WHERE a.monitoring_tier='A' AND o.last_seen_run_id=(SELECT max(run_id) FROM monitoring_runs WHERE requested_tiers @> ARRAY['A']::text[]) ORDER BY o.opportunity_priority DESC) TO 'exports/tier_a_current_opportunities_2026-08-31.csv' CSV HEADER
\copy (SELECT ev.*,e.company_name,o.title,o.job_url FROM opportunity_change_events ev LEFT JOIN opportunities o USING(opportunity_id) LEFT JOIN employers e USING(employer_id) WHERE ev.run_id IN (SELECT run_id FROM monitoring_runs WHERE requested_tiers @> ARRAY['A']::text[]) ORDER BY ev.event_id) TO 'exports/tier_a_change_events_2026-08-31.csv' CSV HEADER
\copy (SELECT mf.*,e.company_name,ms.source_name,ms.source_url FROM monitoring_fetches mf JOIN monitored_sources ms USING(monitored_source_id) JOIN employers e USING(employer_id) WHERE mf.run_id IN (SELECT run_id FROM monitoring_runs WHERE requested_tiers @> ARRAY['A']::text[]) ORDER BY mf.fetch_id) TO 'exports/tier_a_monitoring_fetches_2026-08-31.csv' CSV HEADER
